class BankAccount:
    def __init__(self):
        self.__balance = 0

    def deposit(self, amount):
        self.__balance += amount

account = BankAccount()
account.deposit(100)
try:
    print(account.__balance)
except AttributeError:
    print("Cannot access private attribute")
